package org.opensourcepingpong.membership;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="memberships") public class Membership { @Id private UUID id; @Column(name="user_id") private UUID userId; @Column(name="member_number") private String memberNumber; @Enumerated(EnumType.STRING) private MembershipStatus status; @Column(name="joined_at") private Instant joinedAt; @Column(name="created_at") private Instant createdAt; @Column(name="updated_at") private Instant updatedAt; protected Membership(){} public Membership(UUID userId,String number){id=UUID.randomUUID();this.userId=userId;memberNumber=number;status=MembershipStatus.ACTIVE;joinedAt=Instant.now();createdAt=joinedAt;updatedAt=joinedAt;} public UUID getUserId(){return userId;} public String getMemberNumber(){return memberNumber;} public MembershipStatus getStatus(){return status;} }
